brand.css:
:root{--brand-hover:#353535;--brand-tint:#ECECEC}
body .primary:hover{background:var(--brand-hover)}body nav button[aria-current=step],body .pill{background:var(--brand-tint);color:var(--primary)}body .choice:has(input:checked){background:var(--brand-tint)}body .dark .eyebrow{color:#FFFFFF}
body #brand{font-style:italic;letter-spacing:-.06em;font-size:36px}body .hero h1{font-weight:900;text-transform:uppercase;letter-spacing:-.055em}body .hero img{border-radius:0}body button{border-radius:3px}
